"""Sensor2Dspincenteringtrainingonly, nofrozenholdout/sourcechanges."""
from pathlib import Path
import json,os,sys,subprocess,time,concurrent.futures,math
import numpy as np
from scalar_ground_mpc_v1 import fixedleg_model
R=Path(__file__).resolve().parent;D=R/'batches/r08_spin_center24';D.mkdir(parents=True,exist_ok=False)
with(D/'PREP.log').open('xb')as f:assert subprocess.run([sys.executable,'-B',str(R/'prepare_spin_center_v1.py')],cwd=R,stdin=subprocess.DEVNULL,stdout=f,stderr=subprocess.STDOUT).returncode==0
rawg=json.loads((R/'nominal_gain_v1.json').read_bytes())['gain'];g={k:np.asarray(v,float)if k in('q','tau','K','A','B','Ad','Bd','P','Q','R')else v for k,v in rawg.items()};m=fixedleg_model(g);k8=.5*(g['K'][2]+g['K'][5])@m['embedding'];Acl=m['A8']-m['B8']@k8[None,:];w=4*math.pi;tf=np.linalg.solve(1j*w*np.eye(8)-Acl,m['B8']).ravel()[4]*(k8[4]+k8[0]/(1j*w));lead=float(np.clip(-np.angle(tf)/w+.01,-.25,.25));(D/'NOMINAL_TRANSFER_HYPOTHESIS.json').write_text(json.dumps(dict(kind='ZEROYAW_SMALLSIGNAL_PHASE_GUIDE_NOT_HIGHSPIN_PROOF',frequency_rad_s=w,gain_abs=float(abs(tf)),phase_rad=float(np.angle(tf)),lead_center_s=lead,k8=k8.tolist(),user_shaper_bypassed_for_internal_centering=True),indent=2),encoding='utf-8')
variants={f'l{i}':dict(center_kp=2.,center_lead_s=float(np.clip(lead+d,-.3,.3)),center_v_cap=.25)for i,d in enumerate((-.08,-.04,0.,.04,.08))};variants['soft']=dict(center_kp=1.,center_lead_s=lead,center_v_cap=.2);jobs=[(v,seed)for v in variants for seed in(202,203,205,208)];env=dict(os.environ,OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',PYTHONIOENCODING='utf-8',PYTHONDONTWRITEBYTECODE='1');basec=dict(yaw_kp=.8,yaw_ki=.5,yaw_integral_limit=15.,yaw_rate_ff=.052)
for n in('run_spin_center_v1.py','spin_center_controller_v1.py','spin_base_v1.py','robot_geometry_constants_v1.py'):(D/n).write_bytes((R/n).read_bytes())
def run(job):
 v,seed=job;case=f'r08_center_{v}_{seed}';cfg=dict(case_id=case,seed=seed,nominal=False,feedback='sensors',duration_s=8,command_at_s=1,controller={**basec,**variants[v]},accel_reference='wheel_midpoint',accel_correction=0,upright_arming_prior=True,mode='spin',yaw_rad_s=4*math.pi,cohort='spincentertrain_not_holdout',notes='internalcenteringafterdriverfilter; torquelimits/envelopepreserved; nosideslipproxyexplicit');p=D/(case+'.json');p.write_text(json.dumps(cfg,indent=2),encoding='utf-8');started=time.time()
 with(D/(case+'.log')).open('xb')as f:proc=subprocess.Popen([sys.executable,'-B',str(R/'run_spin_center_v1.py'),'--config',str(p),'--out',str(R/'results'/case)],cwd=R,env=env,stdin=subprocess.DEVNULL,stdout=f,stderr=subprocess.STDOUT);code=proc.wait()
 p=R/'results'/case/'result.json';r=json.loads(p.read_bytes())if p.exists()else{};row=dict(case=case,variant=v,seed=seed,returncode=code,start=started,end=time.time(),complete=r.get('complete'),pass_=r.get('proposed_gate_passed'),v_rmse=r.get('tail_v_tracking_RMSE'),w=r.get('tail_yawrate_mean_rad_s'),w_rmse=r.get('tail_w_tracking_RMSE'),xy=r.get('xy_displacement_m'),last_center=r.get('spin_center_final'));print(json.dumps(row),flush=True);return row
with concurrent.futures.ThreadPoolExecutor(max_workers=4)as pool:rows=list(pool.map(run,jobs))
summary={v:{'n':4,'pass':sum(r['variant']==v and bool(r['pass_'])for r in rows),'xymax':max((r['xy']or 0)for r in rows if r['variant']==v)}for v in variants};(D/'BATCH_RESULT.json').write_text(json.dumps(dict(kind='R08_SPIN_CENTER_TRAIN_ONLY',variants=variants,summary=summary,rows=rows),indent=2),encoding='utf-8');print('SUMMARY',json.dumps(summary),flush=True)
